$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;Set-Location $root;$out='evidence/issue-141/authority-surface-audit.test.json';$script=Join-Path $PSScriptRoot 'audit-authority-surfaces.ps1';$baseline=@(git -C $root status --porcelain);$protectedBefore=@{}
$paths=@('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/agents','source/global/AGENTS.md','source/adapters','source/registry/execution-grants.json','scripts/v3/lib/OrchestrationTaskKernel.ps1','scripts/v3/lib/OrchestrationNativeDispatchGrantProjection.ps1','scripts/v3/lib/OrchestrationNativeDispatch.ps1','scripts/v3/lib/OrchestrationAutonomy.ps1')
foreach($p in $paths){if(Test-Path $p){$i=Get-Item $p;if($i.PSIsContainer){$fs=Get-ChildItem $p -File -Recurse}else{$fs=@($i)};foreach($f in $fs){$protectedBefore[$f.FullName]=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}}}
try{
 & $script -OutFile $out -GeneratedAt fixed;$j=Get-Content $out -Raw|ConvertFrom-Json
 if(@($j.surfaces).Count -ne 3 -or @($j.cross_surface_tokens).Count -ne 0){throw 'surface/cross-token count mismatch'};if(@($j.permissions).Count -ne 211 -or @($j.protected_files).Count -ne 29 -or @($j.unparseable).Count -ne 0){throw 'permission/protected/unparseable count mismatch'};if(!$j.scan_scope -or ($j.scan_scope -match '(^|/)evidence/') -or !$j.cross_surface_rule -or !$j.surfaces.Where({$_.name -eq 'agent-config'}).no_structured_declarations){throw 'scan scope or Agent Config structured-declaration status invalid'}
 foreach($p in $j.permissions){if(!$p.declared_by){throw 'declaration provenance missing'};if($p.enforcement_kind -notin @('hard','advisory','documented-only')){throw 'invalid enforcement kind'};if($p.enforcement_kind -eq 'hard' -and @($p.tested_by).Count -eq 0){throw "hard without token-specific test proof: $($p.token)"};foreach($ref in @($p.enforced_by)){if(!$ref){continue};if($ref -notmatch '^(.+):(\d+)$'){throw 'bad enforcement ref'};$source=Get-Content $Matches[1];if(!$source[[int]$Matches[2]-1].Contains([string]$p.token)){throw "pooled/unrelated enforcement ref $ref for $($p.token)"}}}
 foreach($token in @('secrets.read','destructive.fs','deploy.production','fs.read')){$kp=$j.permissions|Where-Object{$_.surface -eq 'task-kernel' -and $_.token -eq $token}|Select-Object -First 1;if(!$kp -or !$kp.enforced_by){throw "expected token-specific guard refs for $token"}}
 $secret=$j.permissions|Where-Object{$_.surface -eq 'task-kernel' -and $_.token -eq 'secrets.read'}|Select-Object -First 1;if(@($secret.enforced_by|Where-Object{$_ -eq 'scripts/v3/lib/OrchestrationTaskKernel.ps1:853'}).Count -ne 1){throw 'secrets.read is not mapped to sensitive-grants guard'}
 foreach($guard in $j.surfaces|Where-Object name -eq task-kernel|Select-Object -ExpandProperty guards){foreach($call in $guard.call_sites){if($call.path -match '\.tests\.ps1$'){throw 'call_sites contains test source'};$line=(Get-Content $call.path)[$call.line-1];if($line.Trim() -match '^(#|//|\*|<#)'){throw 'call_sites contains comment'}}}
 $effective=$j.surfaces|Where-Object name -eq task-kernel|Select-Object -ExpandProperty guards|Where-Object name -eq Get-OrchestrationEffectiveGrants;$callIds=@($effective.call_sites|ForEach-Object{"$($_.path):$($_.line)"});if($callIds -notcontains 'scripts/v3/lib/OrchestrationNativeDispatchGrantProjection.ps1:437' -or $callIds -notcontains 'scripts/v3/lib/OrchestrationE2eManifest.ps1:672'){throw 'real effective-grant callers missing'}
 foreach($u in $j.unparseable){if($u.classification -ne 'UNPARSEABLE'){throw 'UNPARSEABLE was silently resolved'}}
 foreach($f in $j.protected_files){if((Get-FileHash $f.path -Algorithm SHA256).Hash -ne $f.sha256){throw "protected hash mismatch $($f.path)"}};foreach($p in $protectedBefore.Keys){if((Get-FileHash $p -Algorithm SHA256).Hash -ne $protectedBefore[$p]){throw "protected file changed $p"}}
 $ids=@($j.permissions|ForEach-Object{"$($_.surface):$($_.declared_by):$($_.token)"});if(@($ids|Select-Object -Unique).Count -ne $ids.Count){throw 'duplicate structured permission record'}
 $temp=Join-Path $env:TEMP ('authority-audit-negative-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory $temp;try{Copy-Item templates/opencode.v1.json.tmpl $temp;Copy-Item templates/opencode.v2.json.tmpl $temp;$bad=Join-Path $temp 'opencode.v1.json.tmpl';Set-Content $bad '{ invalid json' -Encoding UTF8;$negative=Join-Path $env:TEMP ('authority-negative-'+[guid]::NewGuid().ToString('N')+'.json');& $script -OutFile $negative -TemplatesRoot $temp -GeneratedAt fixed;$nj=Get-Content $negative -Raw|ConvertFrom-Json;if(@($nj.unparseable|Where-Object path -like '*opencode.v1.json.tmpl'|Where-Object classification -eq UNPARSEABLE).Count -ne 1){throw 'negative malformed-template case did not produce UNPARSEABLE'};Remove-Item $negative -Force}finally{Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}
 $first=Get-Content $out -Raw;& $script -OutFile $out -GeneratedAt fixed;if($first -ne (Get-Content $out -Raw)){throw 'not deterministic'}
 $changed=@(git -C $root status --porcelain|Where-Object{$_ -notmatch [regex]::Escape($out)});if(($changed -join "`n") -ne ($baseline -join "`n")){throw 'write outside OutFile'};'PASS audit-authority-surfaces'
}finally{Remove-Item $out -ErrorAction SilentlyContinue}
